import React, { useRef } from "react";
import { flexRender } from "@tanstack/react-table";
import { clsx } from "clsx";

import { useTable } from "../hooks/use-table";
import { useTableKeyboardNavContext } from "../hooks/use-table-keyboard-nav-context";
import { TableClasses } from "../table.styles";

export const TableBody = (props: React.HTMLAttributes<HTMLTableSectionElement>) => {
  const {
    getRowModel,
    getHeaderGroups,
    options: { enableRowSelection },
  } = useTable();
  const { enableKeyboardShortcuts, handleKeyDown } = useTableKeyboardNavContext();
  const { rows } = getRowModel();
  const headerRowCount = getHeaderGroups().length;
  const rowRef = useRef<HTMLTableRowElement>(null);

  return (
    <tbody {...props} className={clsx(TableClasses.body, props.className)}>
      {rows.map((row, index) => (
        <tr
          key={row.id}
          ref={index === 0 ? rowRef : null}
          className={clsx(
            TableClasses.bodyRow,
            row.getIsSelected() && "selected",
            row.depth > 0 && TableClasses.bodySubRow,
          )}
          data-expanded={row.getCanExpand() ? row.getIsExpanded() : undefined}
          data-row-depth={row.depth}
        >
          {row.getVisibleCells().map((cell) => (
            <td
              key={cell.id}
              className={TableClasses.bodyCell}
              data-col={enableRowSelection ? cell.column.getIndex() + 1 : cell.column.getIndex()}
              data-column-id={cell.column.id}
              data-row={index + headerRowCount}
              data-row-id={row.id}
              style={{
                // Skip TanStack's defaultColumnSizing (150/20/MAX) so unsized columns auto-distribute under tableLayout: fixed.
                width: cell.column.columnDef.size !== 150 ? cell.column.getSize() : undefined,
                minWidth:
                  cell.column.columnDef.minSize !== 20 ? cell.column.columnDef.minSize : undefined,
                maxWidth:
                  cell.column.columnDef.maxSize !== Number.MAX_SAFE_INTEGER
                    ? cell.column.columnDef.maxSize
                    : undefined,
              }}
              tabIndex={enableKeyboardShortcuts ? 0 : -1}
              onKeyDown={(e) => {
                if (enableKeyboardShortcuts) {
                  handleKeyDown?.(e);
                  if (cell.column.id === "select" && (e.key === "Enter" || e.key === " ")) {
                    row.toggleSelected(!row.getIsSelected());
                  }
                  if (
                    cell.column.id === "expand" &&
                    row.getCanExpand() &&
                    (e.key === "Enter" || e.key === " ")
                  ) {
                    row.toggleExpanded();
                  }
                }
              }}
            >
              {flexRender(cell.column.columnDef.cell, cell.getContext())}
            </td>
          ))}
        </tr>
      ))}
    </tbody>
  );
};

TableBody.displayName = "Table.Body";
